import '../../../shared/repositories/repositories.dart'; import '../../domain/entities.dart'; import '../database/daos/audit_dao.dart'; import '../database/mappers/audit_sync_mappers.dart';
final class LocalAuditRepository implements AuditRepository { const LocalAuditRepository(this.dao); final AuditDao dao; @override Future<List<AuditEvent>> getAuditEvents() async=>(await dao.getAuditEvents()).map((e)=>e.toDomain()).toList(); @override Future<List<AuditEvent>> getAuditEventsForTask(String id) async=>(await dao.getAuditEventsForTask(id)).map((e)=>e.toDomain()).toList(); @override Future<List<AuditEvent>> getAuditEventsForEntity(String type,String id) async=>(await dao.getAuditEventsForEntity(type,id)).map((e)=>e.toDomain()).toList(); @override Future<void> appendAuditEvent(AuditEvent e)=>dao.appendAuditEvent(e.toCompanion()); }
